import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.nio.file.Path;
import java.nio.file.Paths;

public class FileReadSecure {
    public static void main(String[] args) {
        String userInput = "images/photo.jpg"; // In a real app, this comes from a request parameter
        String baseDirectory = "/var/www/html/images"; // Define a strict base directory

        try {
            // Construct the full path using Path objects to ensure it stays within the base directory
            Path base = Paths.get(baseDirectory);
            Path requestedPath = base.resolve(userInput).normalize();

            // Verify that the resolved path is still within the intended base directory
            if (!requestedPath.startsWith(base)) {
                throw new SecurityException("Access denied: Path traversal attempt detected");
            }

            File file = requestedPath.toFile();
            FileInputStream fis = new FileInputStream(file);
            // Logic to read file...
            fis.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
